import{_ as a,a0 as o,w as l,s as p,ao as m,I as n,x as e,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"讓決策更透明的三步 | LCTT x X-CMD","titleTemplate":false,"description":"讓決策更透明的三步 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"讓決策更透明的三步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"讓決策更透明的三步 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20170928 A 3-step process for making more transparent decisions","title":"讓決策更透明的三步","tag":"201811","desc":""},"relativePath":"201811/20170928 A 3-step process for making more transparent decisions.md","filePath":"[post].md"}'),d={name:"201811/20170928 A 3-step process for making more transparent decisions.md"};function u(f,t,g,T,x,h){const s=o("Link");return l(),p("div",null,[t[16]||(t[16]=m('<h1 id="讓決策更透明的三步" tabindex="-1">讓決策更透明的三步 <a class="header-anchor" href="#讓決策更透明的三步" aria-label="Permalink to “讓決策更透明的三步”">​</a></h1><blockquote><p>當您使用這種決策技巧時，可以使你作為一個開源領導人做出決策時更透明。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/GOV_Transparency_A.png?itok=2r47nFJB" alt=""></p><p>要讓你的領導工作更加透明，其中一個最有效的方法就是將一個現有的流程開放給你的團隊進行反饋，然後根據反饋去改變流程。下面這些練習能讓透明度更加切實，並且它有助於讓你在持續評估並調整你的工作的透明度時形成“肌肉記憶”。</p><p>我想説，你可以通過任何流程來完成這項工作 —— 即使有些流程看起來像是“禁區”流程，比如晉升或者調薪。但是如果第一次它對於初步實踐來説太大了，那麼你可能需要從一個不那麼敏感的流程開始，比如旅行批准流程或者為你的團隊尋找空缺候選人的系統。（舉個例子，我在我們的招聘和晉升流程中使用了這種方式）</p><p>開放流程並使其更加透明可以建立你的信譽並增強團隊成員對你的信任。它會使你以一種可能超乎你設想和舒適程度的方式“走在透明的路上”。以這種方式工作確實會產生額外的工作，尤其是在過程的開始階段 —— 但是，最終這種方法對於讓管理者（比如我）對團隊成員更具責任，而且它會更加相容。</p><h3 id="階段一-選擇一個流程" tabindex="-1">階段一：選擇一個流程 <a class="header-anchor" href="#階段一-選擇一個流程" aria-label="Permalink to “階段一：選擇一個流程”">​</a></h3><p><strong>第一步</strong> 想想你的團隊使用的一個普通的或常規的流程，但是這個流程通常不需要仔細檢查。下面有一些例子：</p><ul><li>招聘：如何創建職位描述、如何挑選面試團隊、如何篩選候選人以及如何做出最終的招聘決定。</li><li>規劃：你的團隊或組織如何確定年度或季度目標。</li><li>升職：你如何選擇並考慮升職候選人，並決定誰升職。</li><li>經理績效評估：誰有機會就經理績效提供反饋，以及他們是如何反饋。</li><li>旅遊：旅遊預算如何分配，以及你如何決定是否批准旅行（或提名某人是否旅行）。</li></ul><p>上面的某個例子可能會引起你的共鳴，或者你可能會發現一些你覺得更合適的流程。也許你已經收到了關於某個特定流程的問題，又或者你發現自己屢次解釋某個特定決策的邏輯依據。選擇一些你能夠控制或影響的東西 —— 一些你認為你的成員所關心的東西。</p><p><strong>第二步</strong> 現在回答以下關於這個流程的問題：</p><ul><li>該流程目前是否記錄在一個所有成員都知道並可以訪問的地方？如果沒有，現在就開始創建文檔（不必太詳細；只需要解釋這個流程的不同步驟以及它是如何工作的）。你可能會發現這個過程不夠清晰或一致，無法記錄到文檔。在這種情況下，用你<em>認為</em>理想情況下所應該的方式去記錄它。</li><li>完成流程的文檔是否説明了在不同的點上是如何做出決定？例如，在旅行批准流程中，它是否解釋瞭如何批准或拒絕請求。</li><li>流程的<em>輸入信息</em>是什麼？例如，在確定部門年度目標時，哪些數據用於關鍵績效指標，查找或者採納誰的反饋，誰有機會審查或“簽字”。</li><li>這個過程會做出什麼<em>假設</em>？例如，在升職決策中，你是否認為所有的晉升候選人都會在適當的時間被他們的經理提出。</li><li>流程的<em>輸出物</em>是什麼？例如，在評估經理的績效時，評估的結果是否會與經理共享，該審查報告的任何方面是否會與經理的直接報告更廣泛地共享（例如，改進的領域)？</li></ul><p>回答上述問題時，避免作出判斷。如果這個流程不能清楚地解釋一個決定是如何做出的，那也可以接受。這些問題只是評估現狀的一個機會。</p><p>接下來，修改流程的文檔，直到你對它充分説明了流程並預測潛在的問題感到滿意。</p><h3 id="階段二-收集反饋" tabindex="-1">階段二：收集反饋 <a class="header-anchor" href="#階段二-收集反饋" aria-label="Permalink to “階段二：收集反饋”">​</a></h3><p>下一個階段涉及到與你的成員分享這個流程並要求反饋。分享説起來容易做起來難。</p><p><strong>第一步</strong> 鼓勵人們提供反饋。考慮一下實現此目的的各種機制：</p><ul><li>把這個流程公佈在人們可以在內部找到的地方，並提示他們可以在哪裏發表評論或提供反饋。谷歌文檔可以很好地評論特定的文本或直接提議文本中的更改。</li><li>通過電子郵件分享過程文檔，邀請反饋。</li><li>提及流程文檔，在團隊會議或一對一的談話時要求反饋。</li><li>給人們一個他們可以提供反饋的時間窗口，並在此窗口內定期發送提醒。</li></ul><p>如果你得不到太多的反饋，不要認為沉默就等於認可。你可以試着直接詢問人們，他們為什麼沒有反饋。是因為他們太忙了嗎？這個過程對他們來説不像你想的那麼重要嗎？你清楚地表達了你的要求嗎？</p><p><strong>第二步</strong> 迭代。當你獲得關於流程的反饋時，鼓勵團隊對流程進行修改和迭代。加入改進的想法和建議，並要求確認預期的反饋已經被應用。如果你不同意某個建議，那就接受討論，問問自己為什麼不同意，以及一種方法和另一種方法的優點是什麼。</p><p>設置一個收集反饋和迭代的時間窗口有助於向前推進。一旦收集和審查了反饋，你應當討論和應用它，並且發佈最終的流程供團隊審查。</p><h3 id="階段三-實現" tabindex="-1">階段三：實現 <a class="header-anchor" href="#階段三-實現" aria-label="Permalink to “階段三：實現”">​</a></h3><p>實現一個流程通常是計劃中最困難的階段。但如果你在修改過程中考慮了反饋意見，人們應該已經預料到了，並且可能會更支持你。從上面迭代過程中獲得的文檔是一個很好的工具，可以讓你對實現負責。</p><p><strong>第一步</strong> 審查實施需求。許多可以從提高透明度中獲益的流程只需要做一點不同的事情，但是你確實需要檢查你是否需要其他支持（例如工具）。</p><p><strong>第二步</strong> 設置實現的時間表。與成員一起回顧時間表，這樣他們就知道會發生什麼。如果新流程需要對其他流程進行更改，請確保為人們提供足夠的時間去適應新方式，並提供溝通和提醒。</p><p><strong>第三步</strong> 跟進。在使用該流程 3-6 個月後，與你的成員聯繫，看看進展如何。新流程是否更加透明、更有效、更可預測？你有什麼經驗教訓可以用來進一步改進這個流程嗎？</p><h3 id="關於作者" tabindex="-1">關於作者 <a class="header-anchor" href="#關於作者" aria-label="Permalink to “關於作者”">​</a></h3>',27)),n("p",null,[t[1]||(t[1]=e("Sam Knuth —— 我有幸在 Red Hat 領導客户內容服務團隊；我們生成提供給我們的客户的所有文檔。我們的目標是為客户提供他們在企業中使用開源技術取得成功所需要的洞察力。在 Twitter 上與我聯繫（",-1)),r(s,{href:"https://twitter.com/samfw"},{default:i(()=>[...t[0]||(t[0]=[e("@samfw",-1)])]),_:1}),t[2]||(t[2]=e("）。",-1))]),t[17]||(t[17]=n("hr",null,null,-1)),n("p",null,[t[4]||(t[4]=e("via: ",-1)),r(s,{href:"https://opensource.com/open-organization/17/9/exercise-in-transparent-decisions"},{default:i(()=>[...t[3]||(t[3]=[e("https://opensource.com/open-organization/17/9/exercise-in-transparent-decisions",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("作者：",-1)),r(s,{href:"https://opensource.com/users/samfw"},{default:i(()=>[...t[5]||(t[5]=[e("Sam Knuth",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),r(s,{href:"https://github.com/MarineFish"},{default:i(()=>[...t[6]||(t[6]=[e("MarineFish",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),r(s,{href:"https://github.com/wxy"},{default:i(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=e("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創編譯，",-1)),r(s,{href:"https://linux.cn/"},{default:i(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const L=a(d,[["render",u]]);export{C as __pageData,L as default};
